const input = items[0].json || {};
const message_id = String(input.message_id || '').trim();
return [{ json: { ...input, message_id, targetFolderPath: String(input.targetFolderPath || input.folder_path || '').replace(/^\/+|\/+$/g, ''), graphUrl: `https://graph.microsoft.com/v1.0/me/messages/${encodeURIComponent(message_id)}/attachments?$select=id,name,contentType,size,isInline` } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const input = $('Prepare Graph Request').item.json;
const data = items[0].json || {};
if (data.error) return fail('WF_SAVE_EMAIL_ATTACHMENTS_TO_ONEDRIVE', data.error);
const attachments = (data.value || []).filter(a => !a.isInline);
const target = input.targetFolderPath || 'OneDrive root';
if (!attachments.length) return pass(`No non-inline attachments found.\nVerification status: Passed`, { saved: [], skipped: [] });
const planned = attachments.map(a => ({ attachment_id: a.id, name: a.name, size: a.size, target }));
return pass(`Attachments ready for OneDrive save: ${planned.length}\n${planned.map(p => `- ${p.name} (${p.size || 0} bytes) -> ${p.target}`).join('\n')}\nDuplicate policy: skip existing file; never overwrite without approval.\nVerification status: Passed`, { message_id: input.message_id, plannedSaves: planned, note: 'Import-time setup may add per-attachment download/upload loop for binary transfer.' });
